import type { AnchorHTMLAttributes, HTMLAttributes, LiHTMLAttributes } from "react";

export function NavigationMenu({ className = "", ...props }: HTMLAttributes<HTMLElement>) { return <nav aria-label="Main" className={className} {...props} />; }
export function NavigationMenuList({ className = "", ...props }: HTMLAttributes<HTMLUListElement>) { return <ul className={`co-flex co-items-center co-gap-1 ${className}`.trim()} {...props} />; }
export function NavigationMenuItem({ className = "", ...props }: LiHTMLAttributes<HTMLLIElement>) { return <li className={className} {...props} />; }
export function NavigationMenuLink({ className = "", ...props }: AnchorHTMLAttributes<HTMLAnchorElement>) { return <a className={`co-inline-flex co-h-10 co-items-center co-rounded-md co-px-4 co-text-sm co-font-medium hover:co-bg-black/5 focus-visible:co-ring-2 ${className}`.trim()} {...props} />; }
